import numpy as np
from tensorflow_addons.activations import gelu


def _ref_gelu(x, approximate=True):
    x = tf.convert_to_tensor(x)
    if approximate:
        pi = tf.cast(math.pi, x.dtype)
        coeff = tf.cast(0.044715, x.dtype)
        return 0.5 * x * (
            1.0 + tf.tanh(tf.sqrt(2.0 / pi) * (x + coeff * tf.pow(x, 3))))
    else:
        return 0.5 * x * (
            1.0 + tf.math.erf(x / tf.cast(tf.sqrt(2.0), x.dtype)))


class TestGelu(tf.test.TestCase, parameterized.TestCase):
    @parameterized.named_parameters(("float16", np.float16),
                                    ("float32", np.float32),
                                    ("float64", np.float64))
    def test_gelu(self, dtype):
        x = np.random.rand(2, 3, 4).astype(dtype)
        self.assertAllCloseAccordingToType(gelu(x), _ref_gelu(x))
        self.assertAllCloseAccordingToType(gelu(x, False), _ref_gelu(x, False))

import numpy as np
from tensorflow_addons.activations import gelu


def _ref_gelu(x, approximate=True):
    x = tf.convert_to_tensor(x)
    if approximate:
        pi = tf.cast(math.pi, x.dtype)
        coeff = tf.cast(0.044715, x.dtype)
        return 0.5 * x * (
            1.0 + tf.tanh(tf.sqrt(2.0 / pi) * (x + coeff * tf.pow(x, 3))))
    else:
        return 0.5 * x * (
            1.0 + tf.math.erf(x / tf.cast(tf.sqrt(2.0), x.dtype)))


class TestGelu(tf.test.TestCase, parameterized.TestCase):
    @parameterized.named_parameters(("float16", np.float16),
                                    ("float32", np.float32),
                                    ("float64", np.float64))
    def test_gelu(self, dtype):
        x = np.random.rand(2, 3, 4).astype(dtype)
        self.assertAllCloseAccordingToType(gelu(x), _ref_gelu(x))
        self.assertAllCloseAccordingToType(gelu(x, False), _ref_gelu(x, False))

class Function(
    CallableObject,
    VolatilitySubject,
    s_abc.Function,
    qlkind=ft.SchemaObjectClass.FUNCTION,
    data_safe=True,
):
    def find_object_param_overloads(
        self,
        schema: s_schema.Schema,
        *,
        srcctx: Optional[parsing.ParserContext] = None,
    ) -> Optional[Tuple[List[Function], int]]:
        params = self.get_params(schema)
        if not params.has_objects(schema):
            return None

        new_params = params.objects(schema)
        new_pt = tuple(p.get_type(schema) for p in new_params)

        diff_param = -1
        overloads = []
        sn = self.get_shortname(schema)
        for f in schema.get_functions(sn):
            if f == self:
                continue

            f_params = f.get_params(schema)
            if not f_params.has_objects(schema):
                continue

            ext_params = f_params.objects(schema)
            ext_pt = (p.get_type(schema) for p in ext_params)

            this_diff_param = -1
            non_obj_param_diff = False
            multi_overload = False

            for i, (new_t, ext_t) in enumerate(zip(new_pt, ext_pt)):
                if new_t != ext_t:
                    if new_t.is_object_type() and ext_t.is_object_type():
                        if (
                            this_diff_param != -1
                            or (
                                diff_param != -1
                                and diff_param != this_diff_param
                            )
                            or non_obj_param_diff
                        ):
                            multi_overload = True
                            break
                        else:
                            this_diff_param = i
                    else:
                        non_obj_param_diff = True
                        if this_diff_param != -1:
                            multi_overload = True
                            break

            if this_diff_param != -1:
                if not multi_overload:
                    multi_overload = len(new_params) != len(ext_params)
                if multi_overload:
                    raise errors.UnsupportedFeatureError(...)
                diff_param = this_diff_param
                overloads.append(f)

        if diff_param == -1:
            return None
        return (overloads, diff_param)

