class TUDataset(object):
    def __init__(self, name, use_pandas=False, hidden_size=10, n_split=0,
                 split_ratio=None, max_allow_node=1000, cross_valid=False):
        self.fold = -1
        self.cross_valid = cross_valid

        if split_ratio:
            assert abs(sum(split_ratio) - 1) < 1e-5
            assert len(split_ratio) == n_split
            split_ratio = [0] + split_ratio
            self.fold_start_idx = np.cumsum(
                [np.floor(ratio * len(self.graph_lists)) for ratio in split_ratio])
            self.fold_start_idx = list(map(lambda x: int(x), self.fold_start_idx))

    def set_fold(self, n):
        self.fold = n

    def __len__(self):
        if self.fold != -1:
            return self.fold_start_idx[self.fold + 1] - self.fold_start_idx[self.fold]
        return len(self.graph_lists)

class Storage(BaseStorage):
    def __init__(self, session, existing_id=0, readonly=False):
        self.session = session
        self.opened = False
        self.inventory_index = None
        self.buffer = BufferedDbWriter(self.session)
        self._existing_id = existing_id
        self.session_completed = False
        self.readonly = readonly

    def commit(self):
        """Commit the stored inventory."""
        if self.inventory_index.inventory_index_warnings:
            status = IndexState.PARTIAL_SUCCESS
        else:
            status = IndexState.SUCCESS
        try:
            self.buffer.flush()
            self.session.commit()
            self.inventory_index.complete(status=status)
            self.session.commit()
        finally:
            self.session_completed = True

